  public void updateComparatorOutputLevelAt(BlockPos target) {
    level.updateNeighbourForOutputSignal(target, level.getBlockState(target).getBlock());
  }
}

package com.lothrazar.cyclic.block.battery;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import com.lothrazar.cyclic.block.TileBlockEntityCyclic;
import com.lothrazar.cyclic.util.CapabilityUtil;
import com.lothrazar.cyclic.registry.BlockRegistry;
import com.lothrazar.cyclic.registry.TileRegistry;
import com.lothrazar.library.util.DirectionUtil;
import com.lothrazar.library.cap.EnergyStorageWrapper;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.MenuProvider;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.common.ModConfigSpec;
import net.neoforged.neoforge.energy.IEnergyStorage;
import net.neoforged.neoforge.items.ItemStackHandler;
import net.neoforged.neoforge.items.IItemHandler;

public class TileBattery extends TileBlockEntityCyclic implements MenuProvider {

  public static ModConfigSpec.IntValue MAX;
  public static ModConfigSpec.IntValue SLOT_CHARGING_RATE;
  private Map<Direction, Boolean> poweredSides;
  final EnergyStorageWrapper energy;
  ItemStackHandler batterySlots = new ItemStackHandler(1) {

    @Override
    public boolean isItemValid(int slot, ItemStack stack) {
      return CapabilityUtil.energy(stack) != null;
      //return stack.getCapability(ForgeCapabilities.ENERGY, null).isPresent();
    }

    @Override
    public int getSlotLimit(int slot) {
      return 1;
    }
  };

  static enum Fields {
    FLOWING, N, E, S, W, U, D;
  }

  public TileBattery(BlockPos pos, BlockState state) {
    super(TileRegistry.BATTERY.get(), pos, state);
    this.needsRedstone = 0;
    energy = new EnergyStorageWrapper(MAX.get(), MAX.get());
    flowing = 0;
    poweredSides = new ConcurrentHashMap<Direction, Boolean>();
    for (Direction f : Direction.values()) {
      poweredSides.put(f, false);
    }
  }

  public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, TileBattery e) {
    e.tick();
  }


  public void tick() {
    this.syncEnergy();
    setPercentFilled();
    boolean isFlowing = this.getFlowing() == 1;
    setLitProperty(isFlowing);
    if (isFlowing) {
      this.tickCableFlow();
    }
    this.chargeSlot();
  }

  private void chargeSlot() {
    if (level.isClientSide) {
      return;
    }
    ItemStack slotItem = this.batterySlots.getStackInSlot(0);
    IEnergyStorage itemStackStorage = CapabilityUtil.energy(slotItem); // slotItem.getCapability(ForgeCapabilities.ENERGY, null).orElse(null);
    if (itemStackStorage != null) {
      int extracted = this.energy.extractEnergy(SLOT_CHARGING_RATE.get(), true);
      int accepted = itemStackStorage.receiveEnergy(extracted, true);
      if (accepted > 0) {
        // no sim, fo real
        energy.extractEnergy(accepted, false);
        itemStackStorage.receiveEnergy(accepted, false);
      }
    }
  }

  public void setPercentFilled() {
    BlockState st = this.getBlockState();
    if (st.hasProperty(BlockBattery.PERCENT)) {
      EnumBatteryPercent previousPercent = st.getValue(BlockBattery.PERCENT);
      EnumBatteryPercent percent = calculateRoundedPercentFilled();
      if (percent != previousPercent) {
        this.level.setBlockAndUpdate(worldPosition, st.setValue(BlockBattery.PERCENT, percent));
      }
    }
  }

  public EnumBatteryPercent calculateRoundedPercentFilled() {
    int max = MAX.get();
    int percent = (int) Math.floor((this.getEnergy() * 1.0F) / max * 10.0) * 10;
    //    ut.printf("%d / %d = %d percent%n", this.getEnergy(), MAX, percent);
    if (percent >= 100) {
      return EnumBatteryPercent.ONEHUNDRED;
    }
    else if (percent >= 90) {
      return EnumBatteryPercent.NINETY;
    }
    else if (percent >= 80) {
      return EnumBatteryPercent.EIGHTY;
    }
    else if (percent >= 60) {
      return EnumBatteryPercent.SIXTY;
    }
    else if (percent >= 40) {
      return EnumBatteryPercent.FOURTY;
    }
    else if (percent >= 20) {
      return EnumBatteryPercent.TWENTY;
    }
    return EnumBatteryPercent.ZERO;
  }

  public boolean getSideHasPower(Direction side) {
    return this.poweredSides.get(side);
  }

  public int getSideField(Direction side) {
    return this.getSideHasPower(side) ? 1 : 0;
  }

  public void setSideField(Direction side, int pow) {
    this.poweredSides.put(side, (pow == 1));
  }


  @Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    for (Direction f : Direction.values()) {
      poweredSides.put(f, tag.getBoolean("flow_" + f.getName()));
    }
    if (tag.contains(NBTENERGY)) {
      energy.deserializeNBT(registries, tag.get(NBTENERGY));
    }
    batterySlots.deserializeNBT(registries,tag.getCompound(NBTINV + "batt"));
    super.loadAdditional(tag, registries);
  }

  @Override
  public void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    for (Direction f : Direction.values()) {
      tag.putBoolean("flow_" + f.getName(), poweredSides.get(f));
    }
    tag.put(NBTINV + "batt", batterySlots.serializeNBT(registries));
    tag.putInt("flowing", getFlowing());
    tag.put(NBTENERGY, energy.serializeNBT(registries));
    super.saveAdditional(tag, registries);
  }

  @Override
  public Component getDisplayName() {
    return BlockRegistry.BATTERY.get().getName();
  }

  @Override
  public AbstractContainerMenu createMenu(int i, Inventory playerInventory, Player playerEntity) {
    return new ContainerBattery(i, level, worldPosition, playerInventory, playerEntity);
  }

  private void tickCableFlow() {
    for (final Direction exportToSide : DirectionUtil.getAllInDifferentOrder()) {
      if (this.poweredSides.get(exportToSide)) {
        moveEnergy(exportToSide, MAX.get() / 4);
      }
    }
  }

  public int getFlowing() {
    return flowing;
  }

  public void setFlowing(int flowing) {
    this.flowing = flowing;
  }

  @Override
  public int getField(int id) {
    switch (Fields.values()[id]) {
      case D:
        return this.getSideField(Direction.DOWN);
      case E:
        return this.getSideField(Direction.EAST);
      case N:
        return this.getSideField(Direction.NORTH);
      case S:
        return this.getSideField(Direction.SOUTH);
      case U:
        return this.getSideField(Direction.UP);
      case W:
        return this.getSideField(Direction.WEST);
      case FLOWING:
        return flowing;
    }
    return -1;
  }

  @Override
  public void setField(int field, int value) {
    switch (Fields.values()[field]) {
      case FLOWING:
        flowing = value;
      break;
      case D:
        this.setSideField(Direction.DOWN, value % 2);
      break;
      case E:
        this.setSideField(Direction.EAST, value % 2);
      break;
      case N:
        this.setSideField(Direction.NORTH, value % 2);
      break;
      case S:
        this.setSideField(Direction.SOUTH, value % 2);
      break;
      case U:
        this.setSideField(Direction.UP, value % 2);
      break;
      case W:
        this.setSideField(Direction.WEST, value % 2);
      break;
    }
  }

  @Override
  public IItemHandler getItemHandler(Direction side) {
    return batterySlots;
  }


  @Override
  public IEnergyStorage getEnergyHandler(Direction side) {
    return energy;
  }

}

package com.lothrazar.cyclic.block.clock;

import java.util.HashMap;
import java.util.Map;
import com.lothrazar.cyclic.ModCyclic;
import com.lothrazar.cyclic.block.TileBlockEntityCyclic;
import com.lothrazar.cyclic.registry.BlockRegistry;
import com.lothrazar.cyclic.registry.TileRegistry;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.MenuProvider;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.core.HolderLookup;

public class TileRedstoneClock extends TileBlockEntityCyclic implements MenuProvider {

  static enum Fields {
    TIMER, DELAY, DURATION, POWER, REDSTONE, N, E, S, W, U, D;
  }

  private int delay; //dont let these times be zero !!!
  private int duration;
  private int power;
  private Map<Direction, Boolean> poweredSides = new HashMap<Direction, Boolean>();

  public TileRedstoneClock(BlockPos pos, BlockState state) {
    super(TileRegistry.CLOCK.get(), pos, state);
    timer = 0;
    delay = 60;
    duration = 60;
    power = 15;
    needsRedstone = 0;
    this.facingResetAllOn();
  }

  public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, TileRedstoneClock e) {
    e.tick();
  }

  public void tick() {
    try {
      updateMyState();
    }
    catch (Throwable e) {
      ModCyclic.LOGGER.error("Clock blockstate update error", e);
    }
  }

  private void facingResetAllOn() {
    for (Direction f : Direction.values()) {
      poweredSides.put(f, true);
    }
  }

  public int getPower() {
    return this.power;
  }

  public int getPowerForSide(Direction side) {
    if (this.getSideHasPower(side)) {
      return this.power;
    }
    else {
      return 0;
    }
  }

  public boolean getSideHasPower(Direction side) {
    return this.poweredSides.get(side);
  }

  public int getSideField(Direction side) {
    return this.getSideHasPower(side) ? 1 : 0;
  }

  public void setSideField(Direction side, int pow) {
    this.poweredSides.put(side, (pow == 1));
  }

  private boolean detectAllOff() {
    boolean areAnyOn = false;
    for (Direction f : Direction.values()) {
      areAnyOn = areAnyOn || poweredSides.get(f);
    }
    return !areAnyOn;
  }

  @Override
  public Component getDisplayName() {
    return BlockRegistry.CLOCK.get().getName();
  }

  @Override
  public AbstractContainerMenu createMenu(int i, Inventory playerInventory, Player playerEntity) {
    return new ContainerClock(i, level, worldPosition, playerInventory, playerEntity);
  }

  @Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    delay = tag.getInt("redstone_delay");
    duration = tag.getInt("redstone_duration");
    power = tag.getInt("redstone_power");
    for (Direction f : Direction.values()) {
      poweredSides.put(f, tag.getBoolean(f.getName()));
    }
    if (this.detectAllOff()) {
      this.facingResetAllOn(); //fix legacy data for one
    }
    super.loadAdditional(tag, registries);
  }

  @Override
  public void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    tag.putInt("redstone_delay", delay);
    tag.putInt("redstone_duration", duration);
    tag.putInt("redstone_power", power);
    for (Direction f : Direction.values()) {
      tag.putBoolean(f.getName(), poweredSides.get(f));
    }
    super.saveAdditional(tag, registries);
  }

  private void updateMyState() throws IllegalArgumentException {
    if (this.requiresRedstone() && !this.isPowered()) {
      setLitProperty(false);
      return;
    }
    BlockState blockState = level.getBlockState(worldPosition);
    if (blockState.hasProperty(BlockRedstoneClock.LIT) == false) {
      return;
    }
    if (this.power == 0) {
      level.setBlockAndUpdate(worldPosition, blockState.setValue(BlockRedstoneClock.LIT, false));
      return;
    }
    this.timer++;
    boolean powered;
    boolean prevPowered = blockState.getValue(BlockRedstoneClock.LIT);
    if (timer < delay) {
      powered = false;
    }
    else if (timer < delay + duration) {
      //we are in the ON section
      powered = true;
    }
    else {
      timer = 0;
      powered = false;
    }
    if (prevPowered != powered) {
      level.setBlockAndUpdate(worldPosition, blockState.setValue(BlockRedstoneClock.LIT, powered));
      //super weird hotfix for down state not updating
      //all other directions read update, but not down apparently!
      //      world.notifyNeighborsOfStateChange(pos.down(), world.getBlockState(pos.down()).getBlock(), true);
    }
  }

  @Override
  public int getField(int id) {
    switch (Fields.values()[id]) {
      case POWER:
        return power;
      case TIMER:
        return timer;
      case DELAY:
        return delay;
      case DURATION:
        return duration;
      case REDSTONE:
        return this.needsRedstone;
      case D:
        return this.getSideField(Direction.DOWN);
      case E:
        return this.getSideField(Direction.EAST);
      case N:
        return this.getSideField(Direction.NORTH);
      case S:
        return this.getSideField(Direction.SOUTH);
      case U:
        return this.getSideField(Direction.UP);
      case W:
        return this.getSideField(Direction.WEST);
    }
    return 0;
  }

  @Override
  public void setField(int id, int value) {
    switch (Fields.values()[id]) {
      case POWER:
        if (value < 0) {
          value = 0;
        }
        if (value > 15) {
          value = 15;
        }
        power = value;
      break;
      case TIMER:
        timer = value;
      break;
      case DELAY:
        delay = Math.max(value, 1);
      break;
      case DURATION:
        duration = Math.max(value, 1);
      break;
      case REDSTONE:
        this.needsRedstone = value % 2;
      break;
      case D:
        this.setSideField(Direction.DOWN, value % 2);
      break;
      case E:
        this.setSideField(Direction.EAST, value % 2);
      break;
      case N:
        this.setSideField(Direction.NORTH, value % 2);
      break;
      case S:
        this.setSideField(Direction.SOUTH, value % 2);
      break;
      case U:
        this.setSideField(Direction.UP, value % 2);
      break;
      case W:
        this.setSideField(Direction.WEST, value % 2);
      break;
    }
  }
}

package com.lothrazar.cyclic.block.detectorentity;

import java.util.List;
import com.lothrazar.cyclic.ModCyclic;
import com.lothrazar.cyclic.block.TileBlockEntityCyclic;
import com.lothrazar.cyclic.data.PreviewOutlineType;
import com.lothrazar.cyclic.item.datacard.EntityDataCard;
import com.lothrazar.cyclic.registry.BlockRegistry;
import com.lothrazar.cyclic.registry.ItemRegistry;
import com.lothrazar.cyclic.registry.TileRegistry;
import com.lothrazar.library.data.EntityFilterType;
import com.lothrazar.library.util.ShapeUtil;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.MenuProvider;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.minecraft.core.HolderLookup;
import net.neoforged.neoforge.items.ItemStackHandler;

public class TileDetector extends TileBlockEntityCyclic implements MenuProvider {

  static enum Fields {
    GREATERTHAN, LIMIT, RANGEX, RANGEY, RANGEZ, ENTITYTYPE, RENDER;
  }

  private static final int PER_TICK = 10;
  public static final int MAX_RANGE = 32;
  private int rangeX = 5;
  private int rangeY = 1;
  private int rangeZ = 5;
  //default is > 0 living entities 
  private int limitUntilRedstone = 0;
  private CompareType compType = CompareType.GREATER;
  public EntityFilterType entityFilter = EntityFilterType.LIVING;
  private boolean isPoweredNow = false;
  public final ItemStackHandler filter = new ItemStackHandler(1) {

    @Override
    public boolean isItemValid(int slot, ItemStack stack) {
      if (stack.isEmpty()) {
        return true;
      }
      return stack.getItem() == ItemRegistry.ENTITY_DATA.get();
    }

    @Override
    public int getSlotLimit(int slot) {
      return 1;
    }
  };

  public TileDetector(BlockPos pos, BlockState state) {
    super(TileRegistry.DETECTOR_ENTITY.get(), pos, state);
    this.needsRedstone = 0;
  }

  public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, TileDetector e) {
    e.tick();
  }

  public void tick() {
    timer--;
    if (level.isClientSide || timer > 0) {
      return;
    }
    timer = PER_TICK;
    //and then
    int entitiesFound = getCountInRange();
    boolean trigger = false;
    switch (this.compType) {
      case LESS:
        trigger = (entitiesFound < limitUntilRedstone);
      break;
      case GREATER:
        trigger = (entitiesFound > limitUntilRedstone);
      break;
      case EQUAL:
        trigger = (entitiesFound == limitUntilRedstone);
      break;
      default:
      break;
    }
    if (isPoweredNow != trigger) {
      isPoweredNow = trigger;
      BlockState state = level.getBlockState(this.getBlockPos());
      level.sendBlockUpdated(this.getBlockPos(), state, state, 3);
      try {
        level.updateNeighborsAt(this.getBlockPos(), this.getBlockState().getBlock());
      }
      catch (Throwable e) {
        //somehow this lead to a  
        //        java.lang.NullPointerException
        //        at net.minecraft.block.BlockDoor.neighborChanged(BlockDoor.java:228)
        // from the notifyNeighborsOfStateChange(...)
        // door was doing a get state on pos.up() , so its top half..
        //this catch means no game crash 
        ModCyclic.LOGGER.error("State change error in adjacent block ", e);
      }
    }
  }


  @Override
  public Component getDisplayName() {
    return BlockRegistry.DETECTOR_ENTITY.get().getName();
  }

  @Override
  public AbstractContainerMenu createMenu(int i, Inventory playerInventory, Player playerEntity) {
    return new ContainerDetector(i, level, worldPosition, playerInventory, playerEntity);
  }

  @Override
  public boolean isPowered() {
    return isPoweredNow;
  }

  public List<BlockPos> getShapeHollow() {
    return getShape();
  }

  public List<BlockPos> getShape() {
    return ShapeUtil.getShape(getRange(), worldPosition.getY());
  }

  private int getCountInRange() {
    ItemStack filterSta = filter.getStackInSlot(0);
    if (EntityDataCard.hasEntity(filterSta)) {
      //card present: ignore the Type button and count entities matching the card's stored entity type
      AABB range = getRange();
      List<Entity> all = level.getEntitiesOfClass(Entity.class, range);
      int count = 0;
      for (Entity e : all) {
        if (EntityDataCard.matchesEntity(e, filterSta)) {
          count++;
        }
      }
      return count;
    }
    List<? extends LivingEntity> list = this.entityFilter.getEntities(level, getRange());
    return list.size();
  }

  private AABB getRange() {
    double x = worldPosition.getX();
    double y = worldPosition.getY();
    double z = worldPosition.getZ();
    AABB entityRange = new AABB(
        x - this.rangeX, y - this.rangeY, z - this.rangeZ,
        x + this.rangeX + 1, y + this.rangeY, z + this.rangeZ + 1);
    return entityRange;
  }

  @Override
  public int getField(int f) {
    switch (Fields.values()[f]) {
      case ENTITYTYPE:
        return this.entityFilter.ordinal();
      case GREATERTHAN:
        return this.compType.ordinal();
      case LIMIT:
        return this.limitUntilRedstone;
      case RANGEX:
        return this.rangeX;
      case RANGEY:
        return this.rangeY;
      case RANGEZ:
        return this.rangeZ;
      case RENDER:
        return render;
    }
    return 0;
  }

  @Override
  public void setField(int field, int value) {
    switch (Fields.values()[field]) {
      case RENDER:
        this.render = value % PreviewOutlineType.values().length;
      break;
      case GREATERTHAN:
        if (value >= CompareType.values().length) {
          value = 0;
        }
        if (value < 0) {
          value = CompareType.values().length - 1;
        }
        this.compType = CompareType.values()[value];
      break;
      case LIMIT:
        if (value > 999) {
          value = 999;
        }
        if (value < 0) {
          value = 0;
        }
        this.limitUntilRedstone = value;
      break;
      case RANGEX:
        this.rangeX = value;
      break;
      case RANGEY:
        this.rangeY = value;
      break;
      case RANGEZ:
        this.rangeZ = value;
      break;
      case ENTITYTYPE:
        if (value >= EntityFilterType.values().length) {
          value = 0;
        }
        if (value < 0) {
          value = EntityFilterType.values().length - 1;
        }
        this.entityFilter = EntityFilterType.values()[value];
      break;
    }
  }

  @Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    this.rangeX = tag.getInt("ox");
    this.rangeY = tag.getInt("oy");
    this.rangeZ = tag.getInt("oz");
    this.limitUntilRedstone = tag.getInt("limit");
    int cType = tag.getInt("compare");
    if (cType >= 0 && cType < CompareType.values().length) {
      this.compType = CompareType.values()[cType];
    }
    int eType = tag.getInt("entityType");
    if (eType >= 0 && eType < EntityFilterType.values().length) {
      this.entityFilter = EntityFilterType.values()[eType];
    }
    if (tag.contains("filter")) {
      filter.deserializeNBT(registries, tag.getCompound("filter"));
    }
    super.loadAdditional(tag, registries);
  }

  @Override
  public void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    tag.putInt("ox", rangeX);
    tag.putInt("oy", rangeY);
    tag.putInt("oz", rangeZ);
    tag.putInt("limit", limitUntilRedstone);
    tag.putInt("compare", compType.ordinal());
    tag.putInt("entityType", entityFilter.ordinal());
    tag.put("filter", filter.serializeNBT(registries));
    super.saveAdditional(tag, registries);
  }
}

