import net.minecraft.world.item.component.CustomData;
import net.neoforged.neoforge.items.IItemHandler;

public class TileShapedata extends TileBlockEntityCyclic implements MenuProvider {

  private static final int SLOT_A = 0;
  private static final int SLOT_B = 1;
  private static final int SLOT_CARD = 2;
  ItemStackHandler inventory = new ItemStackHandler(3) {

    @Override
    public int getSlotLimit(int slot) {
      return 1;
    }

    @Override
    public boolean isItemValid(int slot, ItemStack stack) {
      if (slot == SLOT_A || slot == SLOT_B) {
        return stack.getItem() instanceof LocationGpsCard;
      }
      else {
        return stack.getItem() instanceof ShapeCard;
      }
    }
  };
  private RelativeShape copiedShape;
  private int hasStashIfOne;

  static enum Fields {
    RENDER, COMMAND, STASH;
  }

  static enum StructCommands {
    READ, COPY, MERGE, PASTE;
  }

  /**
   * packet to trigger this from custom btn
   *
   * @param cmd
   */
  public void execute(StructCommands cmd) {

    ItemStack shapeCard = inventory.getStackInSlot(SLOT_CARD);
    if (!(shapeCard.getItem() instanceof ShapeCard)) {
      return;
    }
    RelativeShape cardShape = RelativeShape.read(shapeCard);
    switch (cmd) {
      case READ:
        BlockPos invA = getTarget(SLOT_A);
        BlockPos invB = getTarget(SLOT_B);
        if (invA != null && invB != null) {
          List<BlockPos> shape = ShapeUtil.rect(invA, invB);
          RelativeShape worldShape = new RelativeShape(level, shape, this.worldPosition);
          //read from WORLD to CARD
          //only works if all three cards set
          worldShape.write(shapeCard);
          /// shape set
        }
      break;
      case COPY:
        //copy shape from CARD to BUFFER
        //only works
        this.copiedShape = new RelativeShape(cardShape);
      break;
      case PASTE:
        //from BUFFER to CARD
        //only works on EMPTY CARDS
        if (this.copiedShape != null && shapeCard.has(DataComponents.CUSTOM_DATA)) {
          //
          shapeCard.remove(DataComponents.CUSTOM_DATA); //paste and not merge so overwrite
          this.copiedShape.write(shapeCard);
        }
      break;
      case MERGE:
        //from BUFFER to CARD
        //only works on NOT EMPTY cards
        if (this.copiedShape != null && cardShape.getShape().size() > 0) {
          //  
          cardShape.merge(this.copiedShape);
          cardShape.write(shapeCard);
        }
      break;
    }
  }

  public TileShapedata(BlockPos pos, BlockState state) {
    super(TileRegistry.COMPUTER_SHAPE.get(), pos, state);
  }

  public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, TileShapedata e) {
    e.tick();
  }

  @Override
  public Component getDisplayName() {
    return BlockRegistry.COMPUTER_SHAPE.get().getName();
  }

  @Override
  public AbstractContainerMenu createMenu(int i, Inventory playerInventory, Player playerEntity) {
    return new ContainerShapedata(i, level, worldPosition, playerInventory, playerEntity);
  }


  @Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    ((ItemStackHandler)inventory).deserializeNBT(registries, tag.getCompound(NBTINV));
    if (tag.contains("copiedShape")) {
      CompoundTag cs = (CompoundTag) tag.get("copiedShape");
      this.copiedShape = RelativeShape.read(cs);
    }
    hasStashIfOne = tag.getInt("stashToggle");
    super.loadAdditional(tag,registries);
  }

  @Override
  public void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    tag.putInt("stashToggle", hasStashIfOne);
    if (this.copiedShape != null) {
      CompoundTag copiedShapeTags = this.copiedShape.write(new CompoundTag());
      tag.put("copiedShape", copiedShapeTags);
    }
    tag.put(NBTINV, ((ItemStackHandler)inventory).serializeNBT(registries));
    super.saveAdditional(tag,registries);
  }

  //  @Override
  public void tick() {
    if (level.isClientSide == false) {
      hasStashIfOne = (this.copiedShape == null) ? 0 : 1;
    }
  }

  /**
   * is command available for use
   *
   * @param shape
   * @return
   */
  public boolean isAvailable(StructCommands shape) {
    ItemStack stack = inventory.getStackInSlot(SLOT_CARD);
    if (stack.isEmpty()) {
      return false;
    }
    boolean cardEmpty = stack.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag() == null
        || !stack.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag().getBoolean(RelativeShape.VALID_SHAPE);
    BlockPos invA = getTarget(SLOT_A);
    BlockPos invB = getTarget(SLOT_B);
    boolean hasTargets = invA != null && invB != null;
    switch (shape) {
      case COPY:
        //dont check stash, copy always overwrites. just need a red card
        return !cardEmpty;
      case MERGE:
        //both card and stash have valid shapes to merge
        return !cardEmpty && this.hasStashIfOne == 1;
      case PASTE:
        //pasting my shape into an empty card
        return cardEmpty && this.hasStashIfOne == 1;
      case READ:
        return cardEmpty && hasTargets;
    }
    return true;
  }

  public BlockPos getTarget(int s) {
    ItemStack stackA = inventory.getStackInSlot(s);
    BlockPosDim loc = LocationGpsCard.getPosition(stackA);
    return loc == null ? null : loc.getPos();
  }

  @Override
  public int getField(int field) {
    switch (Fields.values()[field]) {
      case COMMAND:
        return 0; //unused 
      case RENDER:
        return this.render;
      case STASH:
        return hasStashIfOne;
    }
    return 0;
  }

  @Override
  public void setField(int field, int value) {
    switch (Fields.values()[field]) {
      case STASH:
        hasStashIfOne = value;
      break;
      case COMMAND:
        if (value >= StructCommands.values().length) {
          value = 0;
        }
        StructCommands cmd = StructCommands.values()[value];
        this.execute(cmd);
      break;
      case RENDER:
        this.render = value % PreviewOutlineType.values().length;
      break;
    }
  }

  @Override
  public IItemHandler getItemHandler(Direction side) {
    return inventory;
  }

}

package com.lothrazar.cyclic.block.soundrecord;

import java.util.ArrayList;
import java.util.List;
import com.lothrazar.cyclic.block.TileBlockEntityCyclic;
import com.lothrazar.cyclic.item.datacard.SoundCard;
import com.lothrazar.cyclic.registry.BlockRegistry;
import com.lothrazar.cyclic.registry.ItemRegistry;
import com.lothrazar.cyclic.registry.TileRegistry;
import com.lothrazar.library.cap.ItemStackHandlerWrapper;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.NonNullList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.MenuProvider;
import net.minecraft.world.WorldlyContainer;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.items.ItemStackHandler;
import net.minecraft.core.Direction;
import net.neoforged.neoforge.items.IItemHandler;

public class TileSoundRecorder extends TileBlockEntityCyclic implements MenuProvider, WorldlyContainer {

  static final int MAX_SOUNDS = 10; // locked by gui size. 
  private static final String SOUNDAT = "soundat";
  private static final String IGNORED = "ignored";

  static enum Fields {
    CLEARALL, IGNORE, SAVE;
  }

  ItemStackHandler inputSlots = new ItemStackHandler(1) {

    @Override
    public boolean isItemValid(int slot, ItemStack stack) {
      return stack.getItem() == ItemRegistry.SOUND_DATA.get();
    }
  };
  ItemStackHandler outputSlots = new ItemStackHandler(1);
  private ItemStackHandlerWrapper inventory = new ItemStackHandlerWrapper(inputSlots, outputSlots);
  private NonNullList<String> sounds = NonNullList.withSize(MAX_SOUNDS, "");
  private List<String> ignored = new ArrayList<>();

  public TileSoundRecorder(BlockPos pos, BlockState state) {
    super(TileRegistry.SOUND_RECORDER.get(), pos, state);
  }

  @Override
  public Component getDisplayName() {
    return BlockRegistry.SOUND_RECORDER.get().getName();
  }

  @Override
  public AbstractContainerMenu createMenu(int i, Inventory playerInventory, Player playerEntity) {
    return new ContainerSoundRecorder(i, level, worldPosition, playerInventory, playerEntity);
  }

  @Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    inventory.deserializeNBT(registries,tag.getCompound(NBTINV));
    for (int i = 0; i < MAX_SOUNDS; i++) {
      if (tag.contains(SOUNDAT + i)) {
        sounds.set(i, tag.getString(SOUNDAT + i));
      }
    }
    for (int i = 0; i < MAX_SOUNDS * 100; i++) {
      if (tag.contains(IGNORED + i)) {
        ignored.add(tag.getString(IGNORED + i));
      }
    }
    super.loadAdditional(tag,registries);
  }

  @Override
  public void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    tag.put(NBTINV, inventory.serializeNBT(registries));
    for (int i = 0; i < MAX_SOUNDS; i++) {
      tag.putString(SOUNDAT + i, sounds.get(i));
    }
    for (int i = 0; i < ignored.size(); i++) {
      tag.putString(IGNORED + i, ignored.get(i));
    }
    super.saveAdditional(tag,registries);
  }

  @Override
  public void setField(int field, int value) {
    switch (Fields.values()[field]) {
      case CLEARALL:
        this.clearSounds();
      break;
      case IGNORE:
        this.ignoreSound(value);
      break;
      case SAVE:
        this.saveSoundToCard(value);
      break;
    }
  }

  private void saveSoundToCard(int value) {
    String igme = sounds.get(value);
    if (!inputSlots.getStackInSlot(0).isEmpty()) {
      SoundCard.saveSound(inputSlots.getStackInSlot(0), igme);
    }
  }

  public void ignoreSound(int value) {
    String igme = sounds.get(value);
    if (!ignored.contains(igme)) {
      ignored.add(igme);
    }
    sounds.set(value, "");
  }

  @Override
  public void setFieldString(int field, String value) {
    if (field < MAX_SOUNDS) {
      sounds.set(field, value);
    }
  }

  @Override
  public String getFieldString(int field) {
    if (field < MAX_SOUNDS) {
      return sounds.get(field);
    }
    return "";
  }

  @Override
  public int getField(int field) {
    return 0;
  }

  public void clearSounds() {
    sounds = NonNullList.withSize(MAX_SOUNDS, "");
  }

  public boolean onSoundHeard(String soundIn) {
    if (soundIn != null && !sounds.contains(soundIn) && !ignored.contains(soundIn)) {
      int found = -1; //hacky
      for (int i = 0; i < MAX_SOUNDS; i++) {
        if (sounds.get(i).isEmpty()) {
          found = i;
          break;
        }
      }
      if (found > -1) {
        sounds.set(found, soundIn);
        return true;
      }
    }
    return false;
  }

  @Override
  public IItemHandler getItemHandler(Direction side) {
    return inventory;
  }

  @Override
  public int[] getSlotsForFace(Direction direction) {
    return inventory.getSlotsForFace(direction);
  }

  @Override
  public boolean canPlaceItemThroughFace(int i, ItemStack itemStack,  Direction direction) {
    return inventory.canPlaceItemThroughFace(i, itemStack, direction);
  }

  @Override
  public boolean canTakeItemThroughFace(int i, ItemStack itemStack, Direction direction) {
    return inventory.canTakeItemThroughFace(i, itemStack, direction);
  }
}

package com.lothrazar.cyclic.block.tp;

import com.lothrazar.cyclic.block.BlockCyclic;
import com.lothrazar.library.data.BlockPosDim;
import com.lothrazar.library.util.LevelWorldUtil;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.level.BlockAndTintGetter;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.VoxelShape;
import net.neoforged.neoforge.common.ModConfigSpec;

public class BlockTeleport extends BlockCyclic {

  public static ModConfigSpec.IntValue POWERCONF;
  public static ModConfigSpec.IntValue COSTDIM;
  public static final VoxelShape AABB = Block.box(1.0D, 0.0D, 1.0D, 15.0D, 0.5D, 15.0D);

  public BlockTeleport(Properties properties) {
    super(properties.strength(1.2F).noOcclusion());
    this.setHasGui();
  }

  @Override
  public void entityInside(BlockState state, Level worldIn, BlockPos pos, Entity entity) {
    if (entity instanceof ServerPlayer == false) {
      return;
    }
    ServerPlayer player = (ServerPlayer) entity;
    if (player.isCrouching() == false) {
      return;
    }
    //if im a player, im crouching. anyway just go 
    TileTeleport tile = (TileTeleport) worldIn.getBlockEntity(pos);
    BlockPosDim dimpos = tile.getTargetInSlot(0);
    if (dimpos != null && worldIn instanceof ServerLevel) {
      final int pay = LevelWorldUtil.dimensionIsEqual(dimpos, worldIn) ? POWERCONF.get() : COSTDIM.get();
      int sim = tile.energy.extractEnergy(pay, true);
      if (pay == 0 || sim == pay) {
        tile.energy.extractEnergy(pay, false);
        //tp now
        player.teleportTo(dimpos.getTargetLevel(worldIn),dimpos.getX(),dimpos.getY(),dimpos.getZ(),player.getYRot(),player.getXRot());

      }
    }
  }

  @Override
  protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
    builder.add(LIT);
  }

  @Override
  public VoxelShape getShape(BlockState state, BlockGetter worldIn, BlockPos pos, CollisionContext context) {
    return AABB;
  }

  @Override
  public boolean shouldDisplayFluidOverlay(BlockState state, BlockAndTintGetter world, BlockPos pos, FluidState fluidState) {
    return true;
  }

  @Override
  public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
    return new TileTeleport(pos, state);
  }
}

package com.lothrazar.cyclic.block.tp;

import com.lothrazar.cyclic.block.TileBlockEntityCyclic;
import com.lothrazar.cyclic.item.datacard.LocationGpsCard;
import com.lothrazar.cyclic.registry.BlockRegistry;
import com.lothrazar.cyclic.registry.TileRegistry;
import com.lothrazar.library.cap.EnergyStorageWrapper;
import com.lothrazar.library.data.BlockPosDim;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.MenuProvider;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.items.ItemStackHandler;
import net.minecraft.core.Direction;
import net.neoforged.neoforge.energy.IEnergyStorage;
import net.neoforged.neoforge.items.IItemHandler;

public class TileTeleport extends TileBlockEntityCyclic implements MenuProvider {

  static enum Fields {
    REDSTONE;
  }

  public TileTeleport(BlockPos pos, BlockState state) {
    super(TileRegistry.TELEPORT.get(), pos, state);
    this.needsRedstone = 0;
  }

  static final int MAX = 64000;
  public static final int MAX_TRANSFER = MAX;
  EnergyStorageWrapper energy = new EnergyStorageWrapper(MAX, MAX / 4);
  ItemStackHandler gpsSlots = new ItemStackHandler(1) {

    @Override
    public boolean isItemValid(int slot, ItemStack stack) {
      return stack.getItem() instanceof LocationGpsCard;
    }

    @Override
    public int getSlotLimit(int slot) {
      return 1;
    }
  };

  @Override
  public Component getDisplayName() {
    return BlockRegistry.TELEPORT.get().getName();
  }

  @Override
  public AbstractContainerMenu createMenu(int i, Inventory playerInventory, Player playerEntity) {
    return new ContainerTeleport(i, level, worldPosition, playerInventory, playerEntity);
  }


  @Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    gpsSlots.deserializeNBT(registries,tag.getCompound(NBTINV));
    if (tag.contains(NBTENERGY)) {
      energy.deserializeNBT(registries, tag.get(NBTENERGY));
    }
    super.loadAdditional(tag,registries);
  }

  @Override
  public void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    tag.put(NBTINV, gpsSlots.serializeNBT(registries));
    tag.put(NBTENERGY, energy.serializeNBT(registries));
    super.saveAdditional(tag,registries);
  }

  BlockPosDim getTargetInSlot(int s) {
    return LocationGpsCard.getPosition(gpsSlots.getStackInSlot(s));
  }

  @Override
  public void setField(int field, int value) {
    switch (Fields.values()[field]) {
      case REDSTONE:
        this.needsRedstone = value % 2;
      break;
    }
  }

  @Override
  public int getField(int field) {
    switch (Fields.values()[field]) {
      case REDSTONE:
        return this.needsRedstone;
    }
    return 0;
  }

  public float getRed() {
    return 0.89F;
  }

  public float getBlue() {
    return 0;
  }

  public float getGreen() {
    return 0.12F;
  }

  public float getAlpha() {
    return 0.9F;
  }

  public float getThick() {
